{"title": "二次函数交互演示", "source": "<div id="quadratic-demo" data-viz-keep>
  <style>
    #quadratic-demo { font-variant-numeric: tabular-nums; color: var(--foreground); }
    #quadratic-demo .topline { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
    #quadratic-demo .kicker { margin: 0 0 5px; font-size: 11px; letter-spacing: .08em; color: var(--muted-foreground); }
    #quadratic-demo .title { margin: 0; font-size: 20px; font-weight: 650; line-height: 1.35; letter-spacing: -.01em; }
    #quadratic-demo .reset { flex: none; border: 1px solid var(--viz-grid); border-radius: 999px; background: transparent; color: var(--muted-foreground); font: inherit; font-size: 11px; line-height: 1; padding: 7px 11px; cursor: pointer; transition: color .15s, border-color .15s; }
    #quadratic-demo .reset:hover { color: var(--foreground); border-color: var(--viz-axis); }
    #quadratic-demo .reset:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
    #quadratic-demo .equation-row { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; margin: 13px 0 12px; }
    #quadratic-demo .equation { font-family: var(--font-mono); font-size: clamp(22px, 3vw, 28px); font-weight: 600; line-height: 1.2; letter-spacing: -.02em; }
    #quadratic-demo .badge { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--viz-grid); border-radius: 999px; padding: 4px 9px; font-size: 11px; line-height: 1.2; color: var(--muted-foreground); white-space: nowrap; }
    #quadratic-demo .badge::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--muted-foreground); }
    #quadratic-demo[data-kind="up"] .badge::before { background: var(--viz-series-1); }
    #quadratic-demo[data-kind="down"] .badge::before { background: var(--viz-series-2); }
    #quadratic-demo[data-kind="line"] .badge::before { background: var(--primary); }
    #quadratic-demo .layout { display: grid; grid-template-columns: minmax(0, 1fr) 238px; gap: 18px; align-items: stretch; }
    #quadratic-demo .layout > * { min-width: 0; }
    #quadratic-demo .plot-wrap { border: 1px solid var(--viz-grid); border-radius: 10px; padding: 2px 4px 0; overflow: hidden; }
    #quadratic-demo .plot { position: relative; width: 100%; height: 360px; animation: quad-fade .3s ease-out both; }
    #quadratic-demo .plot svg { display: block; width: 100%; height: 100%; }
    #quadratic-demo .side { display: flex; flex-direction: column; justify-content: center; gap: 9px; }
    #quadratic-demo .side-head { font-size: 11px; letter-spacing: .08em; color: var(--muted-foreground); }
    #quadratic-demo .controls { display: flex; flex-direction: column; gap: 9px; }
    #quadratic-demo .control { border: 1px solid var(--viz-grid); border-radius: 9px; padding: 8px 10px 6px; transition: border-color .15s; }
    #quadratic-demo .control:hover { border-color: var(--viz-axis); }
    #quadratic-demo .ctrl-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 1px; }
    #quadratic-demo .ctrl-head label { font-family: var(--font-mono); font-size: 16px; font-weight: 700; line-height: 1.2; color: var(--foreground); }
    #quadratic-demo .ctrl-head output { min-width: 43px; padding: 1px 6px; border: 1px solid var(--viz-grid); border-radius: 5px; font-family: var(--font-mono); font-size: 12px; line-height: 1.4; text-align: right; color: var(--foreground); }
    #quadratic-demo input[type=range] { -webkit-appearance: none; appearance: none; display: block; width: 100%; height: 18px; margin: 0; padding: 0; background: transparent; accent-color: var(--primary); cursor: pointer; }
    #quadratic-demo input[type=range]::-webkit-slider-runnable-track { height: 4px; border-radius: 999px; background: var(--viz-grid); }
    #quadratic-demo input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 15px; height: 15px; margin-top: -5.5px; border-radius: 50%; background: var(--primary); border: 2px solid var(--background); box-shadow: 0 0 0 1px var(--viz-grid); }
    #quadratic-demo input[type=range]::-moz-range-track { height: 4px; border-radius: 999px; background: var(--viz-grid); }
    #quadratic-demo input[type=range]::-moz-range-thumb { width: 13px; height: 13px; border-radius: 50%; background: var(--primary); border: 2px solid var(--background); box-shadow: 0 0 0 1px var(--viz-grid); }
    #quadratic-demo input[type=range]:focus-visible { outline: 2px solid var(--primary); outline-offset: 4px; border-radius: 4px; }
    #quadratic-demo .ends { display: flex; justify-content: space-between; margin-top: -1px; font-family: var(--font-mono); font-size: 11px; line-height: 1.2; color: var(--muted-foreground); }
    #quadratic-demo .metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--viz-grid); }
    #quadratic-demo .metric { min-width: 0; padding: 0 14px; border-left: 1px solid var(--viz-grid); }
    #quadratic-demo .metric:first-child { border-left: 0; padding-left: 0; }
    #quadratic-demo .metric-label { display: block; margin-bottom: 3px; font-size: 11px; line-height: 1.3; color: var(--muted-foreground); }
    #quadratic-demo .metric-value { display: block; font-family: var(--font-mono); font-size: 14px; font-weight: 600; line-height: 1.35; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    #quadratic-demo .metric-sub { display: block; margin-top: 2px; font-size: 11px; line-height: 1.4; color: var(--muted-foreground); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    #quadratic-demo .hint { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; margin-top: 11px; font-size: 11px; line-height: 1.5; color: var(--muted-foreground); }
    #quadratic-demo .hint b { font-family: var(--font-mono); font-weight: 700; color: var(--foreground); }
    #quadratic-demo .grid-line { stroke: var(--viz-grid); stroke-width: 1; }
    #quadratic-demo .axis-line { stroke: var(--viz-axis); stroke-width: 1.5; }
    #quadratic-demo .tick-text { fill: var(--foreground); font-family: var(--font-mono); font-size: 11px; }
    #quadratic-demo .axis-label { fill: var(--viz-axis); font-family: var(--font-mono); font-size: 13px; font-weight: 700; }
    #quadratic-demo .axis-label-x { text-anchor: end; }
    #quadratic-demo .axis-label-y { text-anchor: start; }
    #quadratic-demo .curve { fill: none; stroke: var(--viz-series-1); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
    #quadratic-demo .sym-line { fill: none; stroke: var(--viz-axis); stroke-width: 1.5; stroke-dasharray: 4 4; opacity: .7; }
    #quadratic-demo .vertex-dot { fill: var(--primary); stroke: var(--background); stroke-width: 2; }
    #quadratic-demo .root-dot { fill: var(--background); stroke: var(--viz-series-1); stroke-width: 2; }
    #quadratic-demo .mark-label { fill: var(--foreground); font-family: var(--font-mono); font-size: 11px; paint-order: stroke; stroke: var(--background); stroke-width: 3px; stroke-linejoin: round; }
    @keyframes quad-fade { from { opacity: 0; transform: translateY(2px); } to { opacity: 1; transform: none; } }
    @media (max-width: 720px) {
      #quadratic-demo .layout { grid-template-columns: minmax(0, 1fr); gap: 12px; }
      #quadratic-demo .plot { height: 300px; }
      #quadratic-demo .side { display: block; }
      #quadratic-demo .controls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; margin-top: 8px; }
      #quadratic-demo .metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 0; }
      #quadratic-demo .metric:nth-child(3) { border-left: 0; padding-left: 0; }
      #quadratic-demo .metric:nth-child(n+3) { margin-top: 11px; padding-top: 11px; border-top: 1px solid var(--viz-grid); }
    }
    @media (max-width: 560px) {
      #quadratic-demo .title { font-size: 18px; }
      #quadratic-demo .controls { grid-template-columns: minmax(0, 1fr); }
      #quadratic-demo .metric { padding: 0 10px; }
    }
    @media (prefers-reduced-motion: reduce) {
      #quadratic-demo .plot { animation: none !important; }
    }
  </style>

  <div class="topline">
    <div>
      <p class="kicker">交互演示 · 二次函数</p>
      <h2 class="title">拖动 a、b、c，观察抛物线</h2>
    </div>
    <button class="reset" type="button">↺ 重置</button>
  </div>

  <div class="equation-row">
    <span class="equation" data-viz-out="equation">y = x²</span>
    <span class="badge" data-viz-out="shape">开口向上</span>
  </div>

  <div class="layout">
    <div class="plot-wrap">
      <div class="plot">
        <svg role="img" aria-label="二次函数图像，随 a、b、c 滑块变化"></svg>
      </div>
    </div>
    <div class="side">
      <div class="side-head">拖动系数</div>
      <div class="controls">
        <div class="control">
          <div class="ctrl-head">
            <label for="quad-a">a</label>
            <output for="quad-a" data-viz-out="a">1.0</output>
          </div>
          <input id="quad-a" name="a" type="range" min="-2" max="2" step="0.1" value="1">
          <div class="ends"><span>−2</span><span>2</span></div>
        </div>
        <div class="control">
          <div class="ctrl-head">
            <label for="quad-b">b</label>
            <output for="quad-b" data-viz-out="b">0.0</output>
          </div>
          <input id="quad-b" name="b" type="range" min="-6" max="6" step="0.1" value="0">
          <div class="ends"><span>−6</span><span>6</span></div>
        </div>
        <div class="control">
          <div class="ctrl-head">
            <label for="quad-c">c</label>
            <output for="quad-c" data-viz-out="c">0.0</output>
          </div>
          <input id="quad-c" name="c" type="range" min="-6" max="6" step="0.1" value="0">
          <div class="ends"><span>−6</span><span>6</span></div>
        </div>
      </div>
    </div>
  </div>

  <div class="metrics">
    <div class="metric">
      <span class="metric-label">顶点</span>
      <span class="metric-value" data-viz-out="vertex">(0, 0)</span>
      <span class="metric-sub" data-viz-out="vertexSub">最低点</span>
    </div>
    <div class="metric">
      <span class="metric-label">对称轴</span>
      <span class="metric-value" data-viz-out="axis">x = 0</span>
      <span class="metric-sub" data-viz-out="axisSub">过顶点且垂直 x 轴</span>
    </div>
    <div class="metric">
      <span class="metric-label">判别式</span>
      <span class="metric-value" data-viz-out="delta">0</span>
      <span class="metric-sub">Δ = b² − 4ac</span>
    </div>
    <div class="metric">
      <span class="metric-label">与 x 轴</span>
      <span class="metric-value" data-viz-out="rootKind">相切于 x 轴</span>
      <span class="metric-sub" data-viz-out="rootDetail">x₁ = x₂ = 0</span>
    </div>
  </div>

  <div class="hint">
    <span><b>a</b> 决定开口与胖瘦 · <b>b</b> 影响对称轴 · <b>c</b> 是 y 轴截距</span>
    <span>图像随参数实时重绘</span>
  </div>
</div>
<script>
(function () {
  var root = document.getElementById('quadratic-demo');
  if (!root) return;
  var NS = 'http://www.w3.org/2000/svg';
  var plot = root.querySelector('.plot');
  var svg = root.querySelector('svg');
  var resetBtn = root.querySelector('.reset');
  var EPS = 1e-9;
  var entered = false;
  var lastParams = null;
  var lastW = 0, lastH = 0;
  var reduced = false;
  try { reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (e) { reduced = false; }

  function el(name, attrs, text) {
    var node = document.createElementNS(NS, name);
    if (attrs) {
      for (var k in attrs) {
        if (Object.prototype.hasOwnProperty.call(attrs, k) && attrs[k] !== null && attrs[k] !== undefined) {
          node.setAttribute(k, attrs[k]);
        }
      }
    }
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function round(n, d) {
    var places = d === undefined ? 1 : d;
    var m = Math.pow(10, places);
    var v = Math.round((Number(n) || 0) * m) / m;
    return v === 0 ? 0 : v;
  }

  function trimNum(n, d) {
    var places = d === undefined ? 1 : d;
    var v = round(n, places);
    var out;
    if (Math.abs(v - Math.round(v)) < 1e-9) out = String(Math.round(v));
    else out = v.toFixed(places);
    return out.replace(/-/g, '−');
  }

  function fixed1(n) {
    return round(n, 1).toFixed(1).replace(/-/g, '−');
  }

  function equationOf(a, b, c) {
    var out = 'y = ';
    if (Math.abs(a) < EPS) {
      if (Math.abs(b) < EPS) return out + trimNum(c, 1);
      out += b === 1 ? 'x' : b === -1 ? '−x' : trimNum(b, 1) + 'x';
      if (Math.abs(c) > EPS) out += (c > 0 ? ' + ' : ' − ') + trimNum(Math.abs(c), 1);
      return out;
    }
    out += a === 1 ? 'x²' : a === -1 ? '−x²' : trimNum(a, 1) + 'x²';
    if (Math.abs(b) > EPS) {
      out += b > 0 ? ' + ' : ' − ';
      out += Math.abs(b) === 1 ? 'x' : trimNum(Math.abs(b), 1) + 'x';
    }
    if (Math.abs(c) > EPS) out += (c > 0 ? ' + ' : ' − ') + trimNum(Math.abs(c), 1);
    return out;
  }

  function niceStep(span, target) {
    if (!isFinite(span) || span <= 0) return 1;
    var raw = span / target;
    var mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
    var norm = raw / mag;
    return (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10) * mag;
  }

  function targetLine(b, c) {
    var half = 4;
    if (Math.abs(b) > EPS) {
      var r = -c / b;
      var y1 = b * (r - half) + c;
      var y2 = b * (r + half) + c;
      var pad = Math.max(1, Math.abs(y2 - y1) * 0.15);
      return {
        xmin: r - half, xmax: r + half,
        ymin: Math.min(y1, y2) - pad, ymax: Math.max(y1, y2) + pad
      };
    }
    var yPad = Math.max(1, Math.abs(c) * 0.18);
    return { xmin: -half, xmax: half, ymin: c - yPad, ymax: c + yPad };
  }

  function targetWindow(a, b, c) {
    if (Math.abs(a) < EPS) return targetLine(b, c);
    var h = -b / (2 * a);
    var k = c - b * b / (4 * a);
    var half = Math.max(2.5, Math.sqrt(4 / Math.abs(a)));
    var reach = Math.abs(a) * half * half;
    var padX = half * 0.06;
    var up = a > 0;
    return {
      xmin: h - half - padX,
      xmax: h + half + padX,
      ymin: up ? k - reach * 0.25 : k - reach * 0.75,
      ymax: up ? k + reach * 0.75 : k + reach * 0.25
    };
  }

  function holds(win, a, b, c) {
    if (Math.abs(a) < EPS) return false;
    var h = -b / (2 * a);
    var k = c - b * b / (4 * a);
    var up = a > 0;
    var spanX = win.xmax - win.xmin;
    var spanY = win.ymax - win.ymin;
    if (spanX <= 0 || spanY <= 0) return false;
    var mx = spanX * 0.08;
    var my = spanY * 0.08;
    if (h < win.xmin + mx || h > win.xmax - mx) return false;
    if (k < win.ymin + my || k > win.ymax - my) return false;
    var yEdge = up ? win.ymax - my : win.ymin + my;
    var xEdge = Math.sqrt(Math.abs((yEdge - k) / a));
    if (!isFinite(xEdge)) return false;
    if (h - xEdge < win.xmin + mx || h + xEdge > win.xmax - mx) return false;
    var ideal = targetWindow(a, b, c);
    var rx = spanX / (ideal.xmax - ideal.xmin);
    var ry = spanY / (ideal.ymax - ideal.ymin);
    if (rx > 1.4 || rx < 0.75 || ry > 1.4 || ry < 0.75) return false;
    var vf = (k - win.ymin) / spanY;
    if (a > 0 ? (vf < 0.10 || vf > 0.40) : (vf < 0.60 || vf > 0.90)) return false;
    return true;
  }

  function chooseWindow(a, b, c, prev) {
    if (prev && Math.abs(a) >= EPS && Math.abs(prev.a) >= EPS && holds(prev, a, b, c)) return prev;
    return targetWindow(a, b, c);
  }

  function shapeOf(a, b) {
    if (Math.abs(a) < EPS) {
      return { kind: 'line', text: Math.abs(b) < EPS ? '退化为常函数' : '退化为一次函数' };
    }
    return a > 0 ? { kind: 'up', text: '开口向上' } : { kind: 'down', text: '开口向下' };
  }

  function rootInfo(a, b, c, disc) {
    if (Math.abs(a) < EPS) {
      if (Math.abs(b) < EPS) {
        if (Math.abs(c) < EPS) return { kind: '与 x 轴重合', detail: '无限多个公共点' };
        return { kind: '无交点', detail: '直线与 x 轴平行' };
      }
      return { kind: '一个交点', detail: 'x = ' + trimNum(-c / b, 1) };
    }
    if (disc > EPS) {
      var r1 = (-b - Math.sqrt(disc)) / (2 * a);
      var r2 = (-b + Math.sqrt(disc)) / (2 * a);
      if (r1 > r2) { var tmp = r1; r1 = r2; r2 = tmp; }
      return {
        kind: '两个交点',
        detail: 'x₁ = ' + trimNum(r1, 1) + ' · x₂ = ' + trimNum(r2, 1),
        roots: [r1, r2]
      };
    }
    if (disc >= -EPS) {
      var r = -b / (2 * a);
      return { kind: '相切于 x 轴', detail: 'x₁ = x₂ = ' + trimNum(r, 1), roots: [r] };
    }
    return {
      kind: '没有实数交点',
      detail: '图像完全在 x 轴' + (a > 0 ? '上方' : '下方')
    };
  }

  function draw(params, animate) {
    var a = params.a, b = params.b, c = params.c;
    var w = Math.max(1, Math.round(plot.clientWidth || 0));
    var h = Math.max(1, Math.round(plot.clientHeight || 0));
    lastW = w;
    lastH = h;

    if (svg.getAttribute('width') !== String(w) || svg.getAttribute('height') !== String(h)) {
      svg.setAttribute('width', String(w));
      svg.setAttribute('height', String(h));
      svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    while (svg.firstChild) svg.removeChild(svg.firstChild);

    var win = chooseWindow(a, b, c, lastParams ? lastParams.win : null);
    var padL = 46, padR = 20, padT = 16, padB = 30;
    var iw = Math.max(30, w - padL - padR);
    var ih = Math.max(30, h - padT - padB);
    var sx = function (x) { return padL + (x - win.xmin) / (win.xmax - win.xmin) * iw; };
    var sy = function (y) { return padT + (win.ymax - y) / (win.ymax - win.ymin) * ih; };

    var defs = el('defs');
    var clip = el('clipPath', { id: 'quadratic-demo-plot-clip' });
    clip.appendChild(el('rect', { x: padL, y: padT, width: iw, height: ih }));
    defs.appendChild(clip);
    svg.appendChild(defs);

    var xStep = niceStep(win.xmax - win.xmin, 8);
    var yStep = niceStep(win.ymax - win.ymin, 7);
    var xTicks = [], yTicks = [];
    for (var tx = Math.ceil(win.xmin / xStep - 1e-9) * xStep; tx <= win.xmax + 1e-9; tx += xStep) xTicks.push(round(tx, 6));
    for (var ty = Math.ceil(win.ymin / yStep - 1e-9) * yStep; ty <= win.ymax + 1e-9; ty += yStep) yTicks.push(round(ty, 6));

    var grid = el('g');
    xTicks.forEach(function (value) {
      grid.appendChild(el('line', { x1: sx(value), y1: padT, x2: sx(value), y2: padT + ih, class: 'grid-line' }));
    });
    yTicks.forEach(function (value) {
      grid.appendChild(el('line', { x1: padL, y1: sy(value), x2: padL + iw, y2: sy(value), class: 'grid-line' }));
    });

    var xVisible = win.ymin <= 0 && 0 <= win.ymax;
    var yVisible = win.xmin <= 0 && 0 <= win.xmax;
    var xAxisY = sy(0);
    var yAxisX = sx(0);
    var xAxis = el('g');
    var yAxis = el('g');

    if (xVisible) {
      xAxis.appendChild(el('line', { x1: padL, y1: xAxisY, x2: padL + iw, y2: xAxisY, class: 'axis-line' }));
      xAxis.appendChild(el('path', { d: 'M' + (padL + iw) + ',' + xAxisY + ' l-7,-3.5 v7 z', fill: 'var(--viz-axis)' }));
      xAxis.appendChild(el('text', {
        class: 'axis-label axis-label-x',
        x: padL + iw,
        y: Math.max(padT + 12, Math.min(xAxisY - 10, padT + ih - 4)),
        'text-anchor': 'end'
      }, 'x'));
    }
    if (yVisible) {
      yAxis.appendChild(el('line', { x1: yAxisX, y1: padT, x2: yAxisX, y2: padT + ih, class: 'axis-line' }));
      yAxis.appendChild(el('path', { d: 'M' + yAxisX + ',' + padT + ' l-3.5,7 h7 z', fill: 'var(--viz-axis)' }));
      yAxis.appendChild(el('text', {
        class: 'axis-label axis-label-y',
        x: Math.min(yAxisX + 10, padL + iw - 16),
        y: padT + 14,
        'text-anchor': 'start'
      }, 'y'));
    }

    function tickText(value, step) {
      var digits = step >= 1 ? 0 : step >= 0.1 ? 1 : 2;
      return trimNum(value, digits);
    }

    var labels = el('g');
    var lastXRight = -Infinity;
    xTicks.forEach(function (value) {
      if (Math.abs(value) < 1e-9) return;
      var label = tickText(value, xStep);
      var px = sx(value);
      var width = label.length * 6.2 + 4;
      if (px - width / 2 < lastXRight + 8) return;
      lastXRight = px + width / 2;
      labels.appendChild(el('text', {
