  function targetLine(b, c) {
    var half = 4;
    if (Math.abs(b) > EPS) {
      var r = -c / b;
      var y1 = b * (r - half) + c;
      var y2 = b * (r + half) + c;
      var pad = Math.max(1, Math.abs(y2 - y1) * 0.15);
      return {
        xmin: r - half, xmax: r + half,
        ymin: Math.min(y1, y2) - pad, ymax: Math.max(y1, y2) + pad
      };
    }
    var yPad = Math.max(1, Math.abs(c) * 0.18);
    return { xmin: -half, xmax: half, ymin: c - yPad, ymax: c + yPad };
  }

  function targetWindow(a, b, c) {
    if (Math.abs(a) < EPS) return targetLine(b, c);
    var h = -b / (2 * a);
    var k = c - b * b / (4 * a);
    var half = Math.max(2.5, Math.sqrt(4 / Math.abs(a)));
    var reach = Math.abs(a) * half * half;
    var padX = half * 0.06;
    var up = a > 0;
    return {
      xmin: h - half - padX,
      xmax: h + half + padX,
      ymin: up ? k - reach * 0.25 : k - reach * 0.75,
      ymax: up ? k + reach * 0.75 : k + reach * 0.25
    };
  }

  function holds(win, a, b, c) {
    if (Math.abs(a) < EPS) return false;
    var h = -b / (2 * a);
    var k = c - b * b / (4 * a);
    var up = a > 0;
    var spanX = win.xmax - win.xmin;
    var spanY = win.ymax - win.ymin;
    if (spanX <= 0 || spanY <= 0) return false;
    var mx = spanX * 0.08;
    var my = spanY * 0.08;
    if (h < win.xmin + mx || h > win.xmax - mx) return false;
    if (k < win.ymin + my || k > win.ymax - my) return false;
    var yEdge = up ? win.ymax - my : win.ymin + my;
    var xEdge = Math.sqrt(Math.abs((yEdge - k) / a));
    if (!isFinite(xEdge)) return false;
    if (h - xEdge < win.xmin + mx || h + xEdge > win.xmax - mx) return false;
    var ideal = targetWindow(a, b, c);
    var rx = spanX / (ideal.xmax - ideal.xmin);
    var ry = spanY / (ideal.ymax - ideal.ymin);
    if (rx > 1.4 || rx < 0.75 || ry > 1.4 || ry < 0.75) return false;
    var vf = (k - win.ymin) / spanY;
    if (a > 0 ? (vf < 0.10 || vf > 0.40) : (vf < 0.60 || vf > 0.90)) return false;
    return true;
  }

  function chooseWindow(a, b, c, prev) {
    if (prev && Math.abs(a) >= EPS && Math.abs(prev.a) >= EPS && holds(prev, a, b, c)) return prev;
    return targetWindow(a, b, c);
  }

  function shapeOf(a, b) {
    if (Math.abs(a) < EPS) {
      return { kind: 'line', text: Math.abs(b) < EPS ? '退化为常函数' : '退化为一次函数' };
    }
    return a > 0 ? { kind: 'up', text: '开口向上' } : { kind: 'down', text: '开口向下' };
  }

  function rootInfo(a, b, c, disc) {
    if (Math.abs(a) < EPS) {
      if (Math.abs(b) < EPS) {
        if (Math.abs(c) < EPS) return { kind: '与 x 轴重合', detail: '无限多个公共点' };
        return { kind: '无交点', detail: '直线与 x 轴平行' };
      }
      return { kind: '一个交点', detail: 'x = ' + trimNum(-c / b, 1) };
    }
    if (disc > EPS) {
      var r1 = (-b - Math.sqrt(disc)) / (2 * a);
      var r2 = (-b + Math.sqrt(disc)) / (2 * a);
      if (r1 > r2) { var tmp = r1; r1 = r2; r2 = tmp; }
      return {
        kind: '两个交点',
        detail: 'x₁ = ' + trimNum(r1, 1) + ' · x₂ = ' + trimNum(r2, 1),
        roots: [r1, r2]
      };
    }
    if (disc >= -EPS) {
      var r = -b / (2 * a);
      return { kind: '相切于 x 轴', detail: 'x₁ = x₂ = ' + trimNum(r, 1), roots: [r] };
    }
    return {
      kind: '没有实数交点',
      detail: '图像完全在 x 轴' + (a > 0 ? '上方' : '下方')
    };
  }

  function draw(params, animate) {
    var a = params.a, b = params.b, c = params.c;
    var w = Math.max(1, Math.round(plot.clientWidth || 0));
    var h = Math.max(1, Math.round(plot.clientHeight || 0));
    lastW = w;
    lastH = h;

    if (svg.getAttribute('width') !== String(w) || svg.getAttribute('height') !== String(h)) {
      svg.setAttribute('width', String(w));
      svg.setAttribute('height', String(h));
      svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    while (svg.firstChild) svg.removeChild(svg.firstChild);

    var win = chooseWindow(a, b, c, lastParams ? lastParams.win : null);
    var padL = 46, padR = 20, padT = 16, padB = 30;
    var iw = Math.max(30, w - padL - padR);
    var ih = Math.max(30, h - padT - padB);
    var sx = function (x) { return padL + (x - win.xmin) / (win.xmax - win.xmin) * iw; };
    var sy = function (y) { return padT + (win.ymax - y) / (win.ymax - win.ymin) * ih; };

    var defs = el('defs');
    var clip = el('clipPath', { id: 'quadratic-demo-plot-clip' });
    clip.appendChild(el('rect', { x: padL, y: padT, width: iw, height: ih }));
    defs.appendChild(clip);
    svg.appendChild(defs);

    var xStep = niceStep(win.xmax - win.xmin, 8);
    var yStep = niceStep(win.ymax - win.ymin, 7);
    var xTicks = [], yTicks = [];
    for (var tx = Math.ceil(win.xmin / xStep - 1e-9) * xStep; tx <= win.xmax + 1e-9; tx += xStep) xTicks.push(round(tx, 6));
    for (var ty = Math.ceil(win.ymin / yStep - 1e-9) * yStep; ty <= win.ymax + 1e-9; ty += yStep) yTicks.push(round(ty, 6));

    var grid = el('g');
    xTicks.forEach(function (value) {
      grid.appendChild(el('line', { x1: sx(value), y1: padT, x2: sx(value), y2: padT + ih, class: 'grid-line' }));
    });
    yTicks.forEach(function (value) {
      grid.appendChild(el('line', { x1: padL, y1: sy(value), x2: padL + iw, y2: sy(value), class: 'grid-line' }));
    });

    var xVisible = win.ymin <= 0 && 0 <= win.ymax;
    var yVisible = win.xmin <= 0 && 0 <= win.xmax;
    var xAxisY = sy(0);
    var yAxisX = sx(0);
    var xAxis = el('g');
    var yAxis = el('g');

    if (xVisible) {
      xAxis.appendChild(el('line', { x1: padL, y1: xAxisY, x2: padL + iw, y2: xAxisY, class: 'axis-line' }));
      xAxis.appendChild(el('path', { d: 'M' + (padL + iw) + ',' + xAxisY + ' l-7,-3.5 v7 z', fill: 'var(--viz-axis)' }));
      xAxis.appendChild(el('text', {
        class: 'axis-label axis-label-x',
        x: padL + iw,
        y: Math.max(padT + 12, Math.min(xAxisY - 10, padT + ih - 4)),
        'text-anchor': 'end'
      }, 'x'));
    }
    if (yVisible) {
      yAxis.appendChild(el('line', { x1: yAxisX, y1: padT, x2: yAxisX, y2: padT + ih, class: 'axis-line' }));
      yAxis.appendChild(el('path', { d: 'M' + yAxisX + ',' + padT + ' l-3.5,7 h7 z', fill: 'var(--viz-axis)' }));
      yAxis.appendChild(el('text', {
        class: 'axis-label axis-label-y',
        x: Math.min(yAxisX + 10, padL + iw - 16),
        y: padT + 14,
        'text-anchor': 'start'
      }, 'y'));
    }

    function tickText(value, step) {
      var digits = step >= 1 ? 0 : step >= 0.1 ? 1 : 2;
      return trimNum(value, digits);
    }

    var labels = el('g');
    var lastXRight = -Infinity;
    xTicks.forEach(function (value) {
      if (Math.abs(value) < 1e-9) return;
      var label = tickText(value, xStep);
      var px = sx(value);
      var width = label.length * 6.2 + 4;
      if (px - width / 2 < lastXRight + 8) return;
      lastXRight = px + width / 2;
      labels.appendChild(el('text', {
        x: px,
        y: (xVisible ? xAxisY + 15 : padT + ih + 15),
        'text-anchor': 'middle',
        class: 'tick-text'
      }, label));
    });

    yTicks.forEach(function (value) {
      if (Math.abs(value) < 1e-9 && xVisible && yVisible) return;
      labels.appendChild(el('text', {
        x: padL - 8,
        y: sy(value) + 3.5,
        'text-anchor': 'end',
        class: 'tick-text'
      }, tickText(value, yStep)));
    });

    if (xVisible && yVisible) {
      labels.appendChild(el('text', {
        x: yAxisX - 6,
        y: xAxisY + 14,
        'text-anchor': 'end',
        class: 'tick-text'
      }, '0'));
    }

    svg.appendChild(grid);
    if (xVisible) svg.appendChild(xAxis);
    if (yVisible) svg.appendChild(yAxis);
    svg.appendChild(labels);

    if (Math.abs(a) >= EPS) {
      var hx = -b / (2 * a);
      var ky = c - b * b / (4 * a);
      svg.appendChild(el('line', {
        x1: sx(hx), y1: padT, x2: sx(hx), y2: padT + ih,
        class: 'sym-line', 'clip-path': 'url(#quadratic-demo-plot-clip)'
      }));
    }

    var d = '';
    var count = Math.min(700, Math.max(160, Math.round(iw * 2)));
    for (var i = 0; i <= count; i += 1) {
      var xx = win.xmin + (win.xmax - win.xmin) * (i / count);
      var yy = a * xx * xx + b * xx + c;
      d += (d === '' ? 'M' : 'L') + sx(xx).toFixed(2) + ',' + sy(yy).toFixed(2);
    }
    var curve = el('path', {
      d: d === '' ? 'M0,0' : d,
      class: 'curve',
      'clip-path': 'url(#quadratic-demo-plot-clip)'
    });
    svg.appendChild(curve);

    if (animate && !reduced) {
      try {
        var len = curve.getTotalLength();
        curve.style.strokeDasharray = String(len);
        curve.style.strokeDashoffset = String(len);
        curve.getBoundingClientRect();
        curve.style.transition = 'stroke-dashoffset 600ms ease-out';
        curve.style.strokeDashoffset = '0';
        curve.addEventListener('transitionend', function () {
          curve.style.strokeDasharray = '';
          curve.style.strokeDashoffset = '';
        }, { once: true });
      } catch (e) { /* keep the plain curve */ }
    }

    var rootLabels = [];
    function addRootLabel(text, px) {
      if (!xVisible || px < padL + 18 || px > padL + iw - 18) return;
      var width = text.length * 6.2 + 6;
      for (var j = 0; j < rootLabels.length; j += 1) {
        var other = rootLabels[j];
        if (Math.abs(px - other.x) < (width + other.w) / 2 + 8) return;
      }
      var yLabel = xAxisY + 30;
      if (yLabel > padT + ih - 3) yLabel = Math.max(padT + 12, xAxisY - 12);
      rootLabels.push({ x: px, w: width });
      svg.appendChild(el('text', {
        x: px,
        y: yLabel,
        'text-anchor': 'middle',
        class: 'mark-label'
      }, text));
    }

    if (Math.abs(a) >= EPS) {
      var vh = -b / (2 * a);
      var vk = c - b * b / (4 * a);
      if (vh >= win.xmin && vh <= win.xmax && vk >= win.ymin && vk <= win.ymax) {
        var vx = sx(vh);
        var vy = sy(vk);
        var vText = '顶点 (' + trimNum(vh, 1) + ', ' + trimNum(vk, 1) + ')';
        var vWidth = vText.length * 6.2 + 8;
        var rightRoom = padL + iw - (vx + 10);
        var placeRight = rightRoom >= vWidth;
        var lx = placeRight ? vx + 10 : vx - 10;
        var ly = vy - 9;
        if (ly < padT + 12) ly = vy + 17;
        ly = Math.max(padT + 12, Math.min(ly, padT + ih - 4));
        svg.appendChild(el('circle', { cx: vx, cy: vy, r: 4, class: 'vertex-dot' }));
        svg.appendChild(el('text', {
          x: lx,
          y: ly,
          'text-anchor': placeRight ? 'start' : 'end',
          class: 'mark-label'
        }, vText));
      }

      var disc = b * b - 4 * a * c;
      if (disc >= -EPS && xVisible) {
        var roots = disc > EPS
          ? [(-b - Math.sqrt(disc)) / (2 * a), (-b + Math.sqrt(disc)) / (2 * a)]
          : [-b / (2 * a)];
        roots.sort(function (u, v) { return u - v; });
        roots.forEach(function (r, index) {
          if (r < win.xmin || r > win.xmax) return;
          svg.appendChild(el('circle', { cx: sx(r), cy: xAxisY, r: 3.8, class: 'root-dot' }));
          var label = disc > EPS
            ? (index === 0 ? 'x₁ = ' : 'x₂ = ') + trimNum(r, 1)
            : 'x₁,₂ = ' + trimNum(r, 1);
          addRootLabel(label, sx(r));
        });
      }
    } else if (xVisible && Math.abs(b) > EPS) {
      var lineRoot = -c / b;
      if (lineRoot >= win.xmin && lineRoot <= win.xmax) {
        svg.appendChild(el('circle', { cx: sx(lineRoot), cy: xAxisY, r: 3.8, class: 'root-dot' }));
        addRootLabel('x = ' + trimNum(lineRoot, 1), sx(lineRoot));
      }
    }

    lastParams = { a: a, b: b, c: c, win: win };
  }

  function setOut(key, value) {
    var node = root.querySelector('[data-viz-out="' + key + '"]');
    if (node) node.textContent = value;
  }

  function render(raw) {
    var a = round(raw.a, 1);
    var b = round(raw.b, 1);
    var c = round(raw.c, 1);
    var eq = equationOf(a, b, c);
    var shape = shapeOf(a, b);
    var vertexValue, vertexSub, axisValue, axisSub, deltaValue, deltaSub, info;

    root.setAttribute('data-kind', shape.kind);

    if (Math.abs(a) >= EPS) {
      var h = -b / (2 * a);
      var k = c - b * b / (4 * a);
      var disc = b * b - 4 * a * c;
      vertexValue = '(' + trimNum(h, 1) + ', ' + trimNum(k, 1) + ')';
      vertexSub = a > 0 ? '最低点' : '最高点';
      axisValue = 'x = ' + trimNum(h, 1);
      axisSub = '过顶点且垂直 x 轴';
      deltaValue = trimNum(disc, 1);
      deltaSub = 'Δ = b² − 4ac';
      info = rootInfo(a, b, c, disc);
    } else {
      vertexValue = '—';
      vertexSub = 'a = 0，图像是直线';
      axisValue = '—';
      axisSub = '没有对称轴';
      deltaValue = '—';
      deltaSub = 'a = 0，判别式不适用';
      info = rootInfo(a, b, c, 0);
    }

    setOut('equation', eq);
    setOut('shape', shape.text);
    setOut('vertex', vertexValue);
    setOut('vertexSub', vertexSub);
    setOut('axis', axisValue);
    setOut('axisSub', axisSub);
    setOut('delta', deltaValue);
    setOut('rootKind', info.kind);
    setOut('rootDetail', info.detail);
    setOut('a', fixed1(a));
    setOut('b', fixed1(b));
    setOut('c', fixed1(c));

    svg.setAttribute('aria-label', '二次函数 ' + eq + ' 的图像，顶点 ' + vertexValue);

    draw({ a: a, b: b, c: c }, !entered);
    entered = true;

    return {
      equation: eq,
      shape: shape.text,
      vertex: vertexValue,
      vertexSub: vertexSub,
      axis: axisValue,
      axisSub: axisSub,
      delta: deltaValue,
      deltaSub: deltaSub,
      rootKind: info.kind,
      rootDetail: info.detail,
      a: fixed1(a),
      b: fixed1(b),
      c: fixed1(c)
    };
  }

  if (resetBtn) {
    resetBtn.addEventListener('click', function () {
      var defaults = { a: 1, b: 0, c: 0 };
      Object.keys(defaults).forEach(function (key) {
        var input = root.querySelector('input[name="' + key + '"]');
        if (!input) return;
        input.value = String(defaults[key]);
        input.dispatchEvent(new Event('input', { bubbles: true }));
      });
    });
  }

  dshViz.bind('#quadratic-demo', render);

  if (typeof ResizeObserver === 'function') {
    var observer = new ResizeObserver(function () {
      if (!lastParams) return;
      var w = Math.round(plot.clientWidth || 0);
      var h = Math.round(plot.clientHeight || 0);
      if (!w || !h || (w === lastW && h === lastH)) return;
      draw({ a: lastParams.a, b: lastParams.b, c: lastParams.c }, false);
    });
    observer.observe(plot);
  }
})();
</script>
</div>"}

