          <div class="ends"><span>−6</span><span>6</span></div>
        </div>
        <div class="control">
          <div class="ctrl-head">
            <label for="quad-c">c</label>
            <output for="quad-c" data-viz-out="c">0.0</output>
          </div>
          <input id="quad-c" name="c" type="range" min="-6" max="6" step="0.1" value="0">
